record.field:
{
    # prestations
    'working_time': {
        '002.00',  # Présences
        '002.08',  # Travail à la maison
    },
    # vacances légales
    'legal_leave': {
        '016.00',  # Congé payé
    },
    # petit chômage
    'small_unemployment': {
        '007.00',  # Petit Chômage
    },
    # vacances extra-légales
    'extra_legal_leave': {
        '011.00',  # Congé extra-légal
        # NOTE "extra-legal leaves for workers from abroad to come back
        # to the country" mentioned in the documentation is not a work
        # entry type defined by EGov 3.0
    },
    # jours fériés
    'public_holiday': {
        '006.00',  # Jour férié
        # NOTE the "Recovery Bank Holiday" work entry type was removed, a public
        # holiday recovery day is now encoded as a compensatory rest below.
    },
    # repos compensatoire dans le cadre de réduction du temps de travail ou du congé-éducation
    'compensatory_rest': {
        '024.00',  # Congé éducation
        '024.04',  # Congé éducation flamand
        '165.00',  # Compensatory rest granted under a sectoral collective agreement on the reduction of working time paid by third parties
        '019.00',  # Compensatory rest as part of a reduction in working time paid at the time of recovery
    },
    # incapacité partielle
    'partial_incapacity': {
        '122.04',  # Incapacité partielle
    },
    # incapacité totale
    'total_incapacity': {
        '010.00',  # Incapacity for work with guaranteed salary - 1st week
        'LEAVE217',  # Incapacity for work paid by the employer until the sickness credit is exhausted (education and public sector)
        '082.00',  # Incapacity for work with guaranteed salary system for workers - 2nd week
        '072.00',  # Incapacity for work with salary supplement for workers - after the 2nd week CCT 12bis/13bis
    },
    # maladie
    'sick_leave': {
        '013.00',  # Congé maladie
        '123.00',  # Maladie de longue durée
        '122.00',  # Jours de maladie après le 30e jour
    },
    # repos d'accouchement
    'maternity_leave': {
        '128.00',  # Congé maternité
        '128.04',  # Maternity leave or maternity leave converted in the event of death or hospitalization of the mother
    },
    # accomplissement de devoir civiques
    'civic_duty': {
        '136.00',  # Civic dity (unpaid)
    },
    # rappel ordinaire sous les armes (réserve militaire)
    'military_reserve_call': {
        '150.00',  # Militia obligation (Unpaid)
    },
    # mandat public
    'public_mandate': {
        '160.00',  # Public mandate (Unpaid)
        '017.49', # Political Leave (Paid)
    },
    # obligation syndicale
    'union_obligation': {
        '021.00',  # Union mission paid by the employer
        '134.00',  # Union mission unpaid by the employer
    },
    # stage ou étude consacrée à l'éducation syndicale
    'union_education': set(),
    # grève
    'strike': {
        '132.00',  # Strike / Lock-out
        '141.00',  # Temporary unemployment due to strike / lockout
    },
    # chomage temporaire
    'temporary_unemployment': {
        '137.16',  # Temporary unemployment in the event of dismissal of a protected worker
        '152.00',  # Temporary unemployment due to technical incident
        '156.50',  # Temporary unemployment due to technical incident
        '157.00',  # Temporary unemployment due to collective closure of the company due to annual holidays
        '157.05',  # Temporary unemployment due to collective closure of the company due to compulsory leave under a collective labor agreement
        '157.10',  # Temporary unemployment due to collective closure of the company for compensatory rest as part of a reduction in working hours
        '141.00',  # Temporary unemployment due to strike or lockout
        '151.00',  # Temporary unemployment due to bad weather
        # NOTE 156.55 has been put in 'unemployment_force_majeure'
    },
    # service militaire
    'military_service': set(),  # Maybe 150.00 ? But it's already used.
    # chomage pour force majeure (cause externe à l'entreprise)
    'unemployment_force_majeure': {
        '156.55',  # Temporary unemployment due to force majeure for medical reasons
    },
    # raison impérieuse
    'compelling_reason': {
        '020.20',  # Justified Reason (Paid)
        '154.00',  # Justified Reason (Unpaid)
        '135.00',  # Unpredictable Reason (Unpaid)
    },
    # absence après naissance d'enfant
    'paternity_leave': {
        '007.05',  # Congé de paternité (Payé par la société)
        '128.05',  # Congé de paternité (Légal)
    },
}

field.p:
You can combine time fields together:


  {'months': 2, 'weeks': 7, 'days': 1}


Would represent a time limit of 2 months, 7 weeks and 1 day.

